uint64_t probe_memcmp(void* src, void* src2) {
    uint64_t start, end;
    struct dsa_hw_desc desc = {};
    desc.opcode = DSA_OPCODE_COMPVAL;
    desc.src_addr = src;
    desc.src2_addr = src2;
    enqcmd(wq_portal, &desc);
    // time polling for completion
    start = rdtsc();
    while (comp.status == 0);
    end = rdtsc();
    return end - start;
}

